import type { Vec2 } from "kaplay"
import { playerObj } from "../game"
import { k, layers, mainSoundVolume } from "../main"
import { starsEmitter } from "../particles"
import { collectVolatileCargo } from "../services/shipUpgradeService"
import { gameSoundService } from "../services/gameSoundService"
import { tags } from "../tags"
import { spawnRing } from "./spawnRing"
import { registerBatchedEntityUpdate } from "../services/entityUpdateService"
import { UI_FONT_SIZES } from "../ui/common"
import { getWorldVisual } from "../visuals/worldVisualCatalog"
import { requirePrimaryVisualSprite } from "../visuals/visualRepresentation"

interface VolatileCargoObjectiveProps {
	pos: Vec2
	onCollect?: () => void
	tags?: string[]
}

const VOLATILE_CARGO_VISUAL = getWorldVisual("volatile-cargo")

export function spawnVolatileCargoObjective(
	props: VolatileCargoObjectiveProps
) {
	let collected = false
	const cargo = k.add([
		k.pos(props.pos),
		k.sprite(requirePrimaryVisualSprite(VOLATILE_CARGO_VISUAL)),
		k.anchor("center"),
		k.rotate(0),
		k.scale(VOLATILE_CARGO_VISUAL.worldScale),
		k.color(255, 145, 45),
		k.opacity(0.95),
		tags.props,
		tags.gameLoop,
		tags.runtimeCullable,
		...(props.tags ?? []),
	])
	const glow = cargo.add([
		k.circle(30),
		k.anchor("center"),
		k.color(255, 110, 25),
		k.opacity(0.12),
		k.z(-1),
		k.layer(layers.gameEffects),
	])
	const ring = cargo.add([
		k.circle(35, { fill: false }),
		k.anchor("center"),
		k.outline(2, k.rgb(255, 145, 45)),
		k.opacity(0.75),
		k.layer(layers.gameEffects),
		k.z(-1),
	])
	registerBatchedEntityUpdate("world", cargo, () => {
		cargo.angle += k.dt() * 8
		glow.opacity = k.wave(0.08, 0.22, k.time() * 3)
		ring.scale = k.vec2(k.wave(0.92, 1.12, k.time() * 2.5))
		if (collected || playerObj.pos.dist(cargo.pos) > 24) return
		collected = collectVolatileCargo()
		if (!collected) return
		props.onCollect?.()

		starsEmitter.emitter.position = cargo.pos.clone()
		starsEmitter.emit(28)
		spawnRing({
			pos: cargo.pos,
			speed: 220,
			intensity: 0.4,
			maxRadius: 90,
			color: k.rgb(255, 145, 45),
		})
		spawnCollectionMessage(cargo.pos)
		gameSoundService.play("powerup1", {
			volume: mainSoundVolume,
			detune: -160,
		})
		k.destroy(cargo)
	})
	return cargo
}

function spawnCollectionMessage(pos: Vec2) {
	const message = k.add([
		k.pos(pos.clone()),
		k.text("CARGO SECURED // DO NOT TAKE HULL DAMAGE", {
			size: UI_FONT_SIZES.small,
			font: "unscii",
		}),
		k.anchor("center"),
		k.layer(layers.gameText),
		k.color(255, 175, 75),
		k.opacity(1),
		k.lifespan(2.2, { fade: 0.7 }),
		{
			elapsed: 0,
		},
		tags.gameLoop,
	])
	registerBatchedEntityUpdate("effects", message, () => {
		message.elapsed += k.dt()
		message.pos.y -= 16 * k.dt()
	})
}
